/// Signed-amount power application (mirrors the silent.rs helper) — used
/// when a debuff must reduce a base stat (e.g. ShacklingPotion's -7
/// Strength). The shared `apply_power_to_creature` early-outs on
/// `amount <= 0`, which silently no-ops temporary-debuff folds.
/// Bead `sts2-rs-zt05u`.
pub(crate) fn apply_power_signed_to_creature(
    state: &mut CombatState,
    target_uid: CreatureUid,
    kind: PowerKind,
    amount: i32,
) {
    if amount == 0 {
        return;
    }
    // C# `ArtifactPower` negates a Debuff-direction application (a negative
    // attribute drain) and consumes a stack; the canonical affliction gate
    // misses signed drains, so consult the signed-debuff gate (no-op for
    // positive restores).
    if amount < 0
        && sts2_core::card_effects::try_consume_artifact_for_signed_debuff(
            state, target_uid, amount,
        )
    {
        return;
    }
    let Some(creature_idx) = state
        .creatures
        .iter()
        .position(|c| c.id == target_uid.0 && c.current_hp > 0)
    else {
        return;
    };
    let existing_uid = state.creatures[creature_idx]
        .powers
        .iter()
        .copied()
        .find(|uid| state.powers.iter().any(|p| p.id == uid.0 && p.kind == kind));
    if let Some(uid) = existing_uid {
        let now_zero = if let Some(pow) = state.powers.get_mut_by_id(uid.0) {
            pow.amount = pow.amount.saturating_add(amount);
            pow.amount == 0
        } else {
            false
        };
        if now_zero {
            // C# `PowerModel.ShouldRemoveDueToAmount` (PowerModel.cs:413) removes
            // an `AllowNegative` attribute power (Strength/Dexterity/Focus) at
            // EXACTLY 0 — a negative result keeps it. A signed drain bringing an
            // existing instance to 0 must drop it, not leave a phantom `(0)`
            // power. Mirrors the ironclad/necrobinder/silent signed-power helpers.
            let pid = uid.0;
            state.powers.retain(|p| p.id != pid);
            state.creatures[creature_idx].powers.retain(|u| u.0 != pid);
        }
        return;
    }
    let next_id_raw = state
        .powers
        .iter()
        .map(|p| p.id.get())
        .max()
        .map_or(1, |m| m.saturating_add(1));
    let new_id = std::num::NonZeroU32::new(next_id_raw).expect("power id non-zero");
    state.powers.push(Power {
        id: new_id,
        kind,
        amount,
        counter: 0,
        applier: None,
        skip_next_tick: false,
    });
    state.creatures[creature_idx]
        .powers
        .push(sts2_core::PowerUid(new_id));
}

/// Resolve a `target: Option<u8>` slot index against `state.enemy_uids`.
/// Returns `None` when the slot is out of range or the target arg is
/// missing (e.g. enemy died between `legal_actions` enumeration and
/// drink resolution). Used by enemy-target potions (Weak / Vulnerable).
///
/// NOTE: the `target` reaching here from `apply(Action::DrinkPotion)` is
/// already a concrete RAW `enemy_uids` index — that arm resolves a `None`
/// target to the first alive enemy's raw index (lib.rs, the C#
/// `DoUsePotion` auto-target) BEFORE dispatching the effect — so this
/// helper indexes `enemy_uids` directly and must NOT re-filter to an
/// alive-only list (that would reinterpret the raw index against a shorter
/// list and mis-target when a dead enemy precedes a live one). Bead
/// `sts2-rs-wdf8`.
pub(crate) fn resolve_enemy_target(
    state: &CombatState,
    target: Option<u8>,
) -> Option<sts2_core::CreatureUid> {
    let idx = usize::from(target?);
    state.enemy_uids.get(idx).copied()
}

